package com.scriptles.cabinet.catalog.repository;
import com.scriptles.cabinet.catalog.entity.Franchise; import com.scriptles.cabinet.catalog.domain.CatalogEntityStatus; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public interface FranchiseRepository extends JpaRepository<Franchise,UUID> { Optional<Franchise> findBySlug(String slug); List<Franchise> findByParentIdAndStatusOrderByNameAsc(UUID parentId,CatalogEntityStatus status); Page<Franchise> findPageByNameContainingIgnoreCase(String name,Pageable pageable); @Query("select f from Franchise f where f.status = :status and lower(f.name) like lower(concat('%',:query,'%')) order by lower(f.name), f.id") List<Franchise> search(@Param("query") String query,@Param("status") CatalogEntityStatus status,Pageable pageable); }
